Worker cleanup queue interface and backend factory.

The cleanup queue provides at-least-once delivery of worker cleanup messages
with lease-based reservations, idempotent enqueue, dead-lettering, and wakeup
notifications. This package defines the abstract :class:`WorkerCleanupQueue`
interface; concrete implementations live in sibling modules (e.g.
``prefect.server.worker_communication.cleanup_queue.memory``) and are loaded by
:func:`get_worker_cleanup_queue` according to the
``PREFECT_SERVER_WORKER_CHANNEL_CLEANUP_QUEUE_STORAGE`` setting.
"""

from __future__ import annotations

import importlib
from abc import ABC, abstractmethod
from typing import Any, Optional
from uuid import UUID

from prefect.settings import get_current_settings

#: Import path of this interface package. When the storage setting points here
#: there is no concrete implementation to load and the factory raises.
INTERFACE_MODULE = "prefect.server.worker_communication.cleanup_queue"


class WorkerCleanupQueue(ABC):
    """
    Abstract interface for a reliable worker cleanup queue.

    Implementations must provide idempotent enqueue, lease-based reservation,
    acknowledgment, release, renewal, expiry, dead-lettering, and wakeup
    notification semantics.
    """

    @abstractmethod
    def clear(self) -> None:
        """Reset all internal queue state."""

    @abstractmethod
    def enqueue(
        self,
        message_id: UUID,
        idempotency_key: str,
        work_pool_id: UUID,
        kind: Any,
        target: dict[str, Any],
        data: Optional[dict[str, Any]] = None,
        work_queue_id: Optional[UUID] = None,
    ) -> Any:
        """Enqueue a cleanup message (idempotent on idempotency_key)."""

    @abstractmethod
    def reserve(
        self,
        work_pool_id: UUID,
        preferred_work_queue_ids: Optional[list[UUID]] = None,
        cleanup_kinds: Optional[list[Any]] = None,
    ) -> Any:
        """Reserve the next available message for a work pool."""

    @abstractmethod
    def ack(
        self, work_pool_id: UUID, message_id: UUID, reservation_token: str
    ) -> Any:
        """Acknowledge successful processing of a reserved message."""

    @abstractmethod
    def release(
        self,
        work_pool_id: UUID,
        message_id: UUID,
        reservation_token: str,
        reason: str,
    ) -> Any:
        """Release a reserved message for redelivery or dead-lettering."""

    @abstractmethod
    def renew(
        self, work_pool_id: UUID, message_id: UUID, reservation_token: str
    ) -> Any:
        """Extend the lease of an active reservation."""

    @abstractmethod
    def read_message(self, work_pool_id: UUID, message_id: UUID) -> Any:
        """Read the stored message for a message id within a work pool."""

    @abstractmethod
    def read_dead_letter(self, work_pool_id: UUID, message_id: UUID) -> Any:
        """Read the dead-letter entry for a message id within a work pool."""

    @abstractmethod
    def read_wakeup_sequence(self, work_pool_id: UUID) -> int:
        """Read the current wakeup sequence counter for a work pool."""

    @abstractmethod
    async def wait_for_wakeup(
        self,
        work_pool_id: UUID,
        after: Optional[int] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        """Wait until the wakeup sequence advances past ``after``."""

    @abstractmethod
    def expire_leases(
        self, work_pool_id: Optional[UUID] = None, limit: Optional[int] = None
    ) -> Any:
        """Scan for expired leases and redeliver or dead-letter them."""


def get_worker_cleanup_queue() -> WorkerCleanupQueue:
    """
    Load and return the configured :class:`WorkerCleanupQueue` implementation.

    The backend module is resolved from the
    ``PREFECT_SERVER_WORKER_CHANNEL_CLEANUP_QUEUE_STORAGE`` setting. The module
    must expose a ``WorkerCleanupQueue`` class.

    Raises:
        ValueError: If the configured module is this interface package itself.
    """
    storage = (
        get_current_settings().server.worker_channel.cleanup_queue_storage
    )

    if storage == INTERFACE_MODULE:
        raise ValueError(
            f"{storage!r} is the worker cleanup queue interface package and does "
            "not provide a concrete WorkerCleanupQueue implementation. Set "
            "PREFECT_SERVER_WORKER_CHANNEL_CLEANUP_QUEUE_STORAGE to a module that "
            "provides a concrete WorkerCleanupQueue implementation."
        )

    module = importlib.import_module(storage)
    implementation = getattr(module, "WorkerCleanupQueue", None)
    if implementation is None:
        raise ValueError(
            f"Module {storage!r} does not provide a concrete WorkerCleanupQueue "
            "implementation."
        )

    return implementation()


__all__ = [
    "WorkerCleanupQueue",
    "get_worker_cleanup_queue",
    "INTERFACE_MODULE",
]
